// Inspect the actual rendered paint, including markings generated by shaders.
// Geometry counts alone cannot detect a second crosswalk baked into the road.
export async function checkCrosswalkPaint(api,check){
 const THREE=await import('../dist/vendor/three.module.js');
 const target=new THREE.WebGLRenderTarget(512,256),pixels=new Uint8Array(512*256*4);
 const camera=new THREE.OrthographicCamera(-7,7,2,-2,.1,40),renderer=api.renderer;
 const previous=renderer.getRenderTarget();
 const brightness=(x,z)=>{
   const projected=new THREE.Vector3(x,0,z).project(camera);
   const px=Math.round((projected.x*.5+.5)*511),py=Math.round((projected.y*.5+.5)*255);
   let total=0;
   for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
     const offset=((py+dy)*512+px+dx)*4;
     total+=pixels[offset]+pixels[offset+1]+pixels[offset+2];
   }
   return total/27;
 };
 try{
   camera.up.set(0,0,-1);
   for(const cross of api.route.crossings)for(const end of [-1,1]){
     const z=cross.z+end*8.8;
     camera.position.set(0,20,z);camera.lookAt(0,0,z);camera.updateMatrixWorld(true);
     renderer.setRenderTarget(target);renderer.render(api.scene,camera);
     renderer.readRenderTargetPixels(target,0,0,512,256,pixels);
     // These gaps lay underneath stripes from the older shader layout.
     for(const [gap,stripe] of [[-.1,-.65],[-1.2,-1.95],[5.4,5.85]]){
       const dark=brightness(gap,z),paint=brightness(stripe,z);
       check(`Crosswalk gap stays unpainted at ${cross.name}, ${end}, x=${gap}`,paint>dark*1.3&&paint-dark>15);
     }
   }
 }finally{renderer.setRenderTarget(previous);target.dispose();}
}
